CREATE VIEW "bi"."v1_party" WITH (security_barrier = true) AS SELECT "t"."id", "t"."version", "t"."name" FROM "public"."party" AS "t"
CREATE VIEW "bi"."v1_sales_invoice" WITH (security_barrier = true) AS SELECT "t"."id", "t"."version", "t"."docstatus", "t"."customer", "l0"."name" AS "customer_name", "t"."posting_date", "t"."total", "t"."seen_at", "t"."is_hold", "t"."at_time" FROM "public"."sales_invoice" AS "t" LEFT JOIN "public"."party" AS "l0" ON "l0"."id" = "t"."customer" WHERE "t"."docstatus" = 1
CREATE VIEW "bi"."v1_sales_invoice__sales_invoice_line" WITH (security_barrier = true) AS SELECT "t"."id", "t"."parent", "t"."idx", "t"."item", "t"."qty", "t"."rate" FROM "public"."sales_invoice_line" AS "t" JOIN "public"."sales_invoice" AS "p" ON "p"."id" = "t"."parent" WHERE "p"."docstatus" = 1
